import{_ as d,o as e,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"与真 Redis 的差异清单","description":"","frontmatter":{"title":"与真 Redis 的差异清单"},"headers":[],"relativePath":"mini-redis-course/divergence.md","filePath":"mini-redis-course/docs/divergence.md"}'),h={name:"mini-redis-course/divergence.md"};function i(o,t,s,n,l,b){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="与真-redis-的差异清单" tabindex="-1">与真 Redis 的差异清单 <a class="header-anchor" href="#与真-redis-的差异清单" aria-label="Permalink to &quot;与真 Redis 的差异清单&quot;">​</a></h1><p>迷你 Redis 是教学实现，不是复刻。全书每一处「本课程简化为……」都在正文当场声明，这里集中登记、各注出处。翻到哪章觉得「真货也这样吗」，先来这里对账——<strong>不在本清单里的行为差异是事故，欢迎指出</strong>。</p><h2 id="总纲" tabindex="-1">总纲 <a class="header-anchor" href="#总纲" aria-label="Permalink to &quot;总纲&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>1</td><td>全部命令只实现教学用到的参数形态：SET 无 NX/PX/KEEPTTL，EXPIRE 无 PX/EXPIREAT，TTL 无 PTTL，ZRANGE 无 REV/BYSCORE/BYLEX，PING 不带 message 参数</td><td>各命令有完整参数面</td><td>各章命令节 + 本页总纲</td></tr><tr><td>2</td><td>多机那一层整体不实现（复制/哨兵/集群）</td><td>完整实现</td><td>第 10 章（视野章声明）</td></tr><tr><td>3</td><td>一切后台线程不做（everysec 后台 fsync、BGSAVE 的 fork 子进程、自动重写触发）</td><td>有专门的后台线程/子进程</td><td>第 8、9 章</td></tr><tr><td>4</td><td>内存占用按「键数」近似</td><td>按字节计（maxmemory），覆盖大值也触线</td><td>第 7 章</td></tr><tr><td>5</td><td>仅 RESP2、只收数组格式命令（不收 telnet 裸文本 inline command）</td><td>RESP2/RESP3 协商，两种口音都收</td><td>第 2 章</td></tr></tbody></table><h2 id="第-2-章-·-resp" tabindex="-1">第 2 章 · RESP <a class="header-anchor" href="#第-2-章-·-resp" aria-label="Permalink to &quot;第 2 章 · RESP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>6</td><td>解码以 JS 字符串为载体、手工折算字节；TCP 分段恰好切开多字节字符时会得到乱码且不报错</td><td>全程在字节层缓冲解码，无此问题</td><td>「演练」第四步边界声明</td></tr></tbody></table><h2 id="第-4-章-·-哈希表" tabindex="-1">第 4 章 · 哈希表 <a class="header-anchor" href="#第-4-章-·-哈希表" aria-label="Permalink to &quot;第 4 章 · 哈希表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>7</td><td>教学哈希函数（31-多项式）</td><td>默认 SipHash（早年 MurmurHash2）</td><td>收束差异笔</td></tr><tr><td>8</td><td>扩容新表一律翻倍</td><td>按已存键数向上取 2 的幂，另有缩容</td><td>收束差异笔</td></tr><tr><td>9</td><td>渐进搬迁每步必到非空桶</td><td>每步至多顺访 10 个空桶</td><td>收束差异笔</td></tr></tbody></table><h2 id="第-5-章-·-跳表与-zset" tabindex="-1">第 5 章 · 跳表与 ZSET <a class="header-anchor" href="#第-5-章-·-跳表与-zset" aria-label="Permalink to &quot;第 5 章 · 跳表与 ZSET&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>10</td><td>排序键比较用 JS 字符串序</td><td>按字节序逐字节比（ASCII 范围内一致）</td><td>排序键一节</td></tr><tr><td>11</td><td>ZRANGE 顺底层遍历切片</td><td>节点带 span 跨度，按名次 O(logN)</td><td>收束差异笔</td></tr><tr><td>12</td><td>分数的 <code>inf</code>/<code>nan</code> 特殊写法不辨</td><td>有完整特殊值处理</td><td>收束差异笔</td></tr><tr><td>13</td><td>zset 单一编码</td><td>小数据用 listpack 紧凑编码，大了换跳表（type 与 encoding 分离）</td><td>对象编码概览</td></tr></tbody></table><h2 id="第-6-章-·-过期删除" tabindex="-1">第 6 章 · 过期删除 <a class="header-anchor" href="#第-6-章-·-过期删除" aria-label="Permalink to &quot;第 6 章 · 过期删除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>14</td><td>定期删除由命令间节流驱动（100ms 一拍），空闲时不跑</td><td>serverCron 定时事件驱动</td><td>定期删除一节</td></tr><tr><td>15</td><td>固定「抽 20 / 25% 重复 / 1ms 预算」的经典口径</td><td>现行实现自适应（active-expire-effort 可调）</td><td>定期删除一节差异声明</td></tr><tr><td>16</td><td>候选池每轮取全名单再抽样</td><td>从哈希桶直接抽</td><td>收束差异笔</td></tr><tr><td>17</td><td>KEYS 只认 <code>*</code>/<code>?</code> 极简通配、只过滤不删</td><td>完整 glob</td><td>演练观察窗</td></tr><tr><td>18</td><td>EXPIRE 非正数＝登记过去的时刻、下一拍删（计入 expired）</td><td>非正数 timeout 当场按 DEL 处理（键事件是 del）</td><td>expire 代码注释</td></tr></tbody></table><h2 id="第-7-章-·-内存淘汰" tabindex="-1">第 7 章 · 内存淘汰 <a class="header-anchor" href="#第-7-章-·-内存淘汰" aria-label="Permalink to &quot;第 7 章 · 内存淘汰&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>19</td><td>idle 用毫秒时间戳、另开一张表</td><td>对象头里的 24bit 秒级时钟，读命中时无条件刷新，不占额外内存</td><td>收束差异笔</td></tr><tr><td>20</td><td>无候选池</td><td>3.0 起 16 槽候选池跨轮记住好候选</td><td>收束差异笔</td></tr><tr><td>21</td><td>策略只实现 noeviction 与 allkeys-lru</td><td>至 8.x 主线八个（8.6 起新增 LRM 系）</td><td>收束差异笔</td></tr><tr><td>22</td><td>CONFIG 只认两个名字、GET 回平数组无通配</td><td>完整 CONFIG 面</td><td>收束差异笔</td></tr><tr><td>23</td><td>内存关只在「新增键」时收取键名单</td><td>读 O(1) 内存计数器，覆盖大值也拦</td><td>收束差异笔</td></tr></tbody></table><h2 id="第-8-章-·-aof" tabindex="-1">第 8 章 · AOF <a class="header-anchor" href="#第-8-章-·-aof" aria-label="Permalink to &quot;第 8 章 · AOF&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>24</td><td>重写同进程同步做</td><td>fork 子进程 + 写时复制，重写期间照常接客</td><td>边界声明（第 9 章补原理半边）</td></tr><tr><td>25</td><td>everysec 无后台线程，钉盘点只挂在写路径</td><td>后台线程每秒必钉一次</td><td>刷盘策略一节</td></tr><tr><td>26</td><td>write 逐笔单写</td><td>按事件循环圈批量 write</td><td>刷盘策略一节</td></tr><tr><td>27</td><td>重写寿命记「剩余秒」</td><td>PEXPIREAT 绝对时刻</td><td>收束差异笔</td></tr><tr><td>28</td><td>多键 DEL 拆单键记账、只记真删掉的</td><td>按原命令传播（dirty 计数门控）</td><td>收束差异笔</td></tr><tr><td>29</td><td>无自动重写触发与损坏修复工具</td><td>auto-aof-rewrite-percentage、redis-check-aof；7.0 起多部式 AOF（base+incremental+manifest）</td><td>收束差异笔</td></tr></tbody></table><h2 id="第-9-章-·-rdb" tabindex="-1">第 9 章 · RDB <a class="header-anchor" href="#第-9-章-·-rdb" aria-label="Permalink to &quot;第 9 章 · RDB&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>简化</th><th>真 Redis</th><th>正文出处</th></tr></thead><tbody><tr><td>30</td><td>照片记在实例内不落盘</td><td>写磁盘上的 dump.rdb，重启自动装</td><td>差异第一笔</td></tr><tr><td>31</td><td>无定时自动快照</td><td>save 60 1000 类触发器</td><td>差异笔</td></tr><tr><td>32</td><td>LOAD 为教学专用命令，剧本先 FLUSHALL 再 LOAD</td><td>启动时对空库自动装载</td><td>演练声明</td></tr><tr><td>33</td><td>格式一行一键 JSON 文本</td><td>紧凑二进制 + CRC64 校验 + LZF 压缩，坏了拒收</td><td>格式一节</td></tr><tr><td>34</td><td>BGSAVE 不实现（SAVE 在主线程同步拍）</td><td>BGSAVE fork 子进程拍照不停写</td><td>边界声明专节</td></tr><tr><td>35</td><td>FLUSHALL 逐键补记 DEL</td><td>传播一条 FLUSHALL</td><td>收束差异笔</td></tr><tr><td>36</td><td>照片与账本互不插手</td><td>两套都开时重启用 AOF；混合持久化（RDB 头 + AOF 尾）仅视野提及</td><td>收束差异笔</td></tr></tbody></table>',18)])])}const E=d(h,[["render",i]]);export{m as __pageData,E as default};
